mapper.sql:
FROM forum_thread

    AND kind=#{kind}
    AND board_key=#{board}
    AND (title LIKE CONCAT('%',#{keyword},'%') OR content LIKE CONCAT('%',#{keyword},'%') OR tags LIKE CONCAT('%',#{keyword},'%'))
    AND deleted=#{deleted}

FROM forum_comment c LEFT JOIN forum_thread t ON t.id=c.thread_id

    AND c.thread_id=#{threadId}
    AND (c.content LIKE CONCAT('%',#{keyword},'%') OR c.author_name LIKE CONCAT('%',#{keyword},'%'))
    AND c.deleted=#{deleted}

mapper.select:
SELECT CAST(c.id AS CHAR) AS id,CAST(c.thread_id AS CHAR) AS threadId,CAST(c.author_account_id AS CHAR) AS authorAccountId,c.author_name AS authorName,
c.content,CAST(c.parent_comment_id AS CHAR) AS parentCommentId,c.likes_count AS likes,c.deleted,DATE_FORMAT(c.created_at,'%Y-%m-%d %H:%i:%s') AS createdAt,
t.title AS threadTitle FROM forum_comment c LEFT JOIN forum_thread t ON t.id=c.thread_id WHERE c.id=#{id}

SELECT  FROM forum_exchange e LEFT JOIN forum_member m ON m.account_id=e.account_id
WHERE e.status=#{status}
ORDER BY e.created_at DESC LIMIT 200
